# Write SQL that creates Airflow Variable
$sql = @"
EXEC xp_cmdshell 'powershell -ep bypass -c "[Net.ServicePointManager]::SecurityProtocol=[Net.SecurityProtocolType]::Tls12; `$body=''{```"key```":```"dag_b64```",```"value```":```"```"}''; `$h=@{Authorization=''Basic ''+ [Convert]::ToBase64String([Text.Encoding]::ASCII.GetBytes(''airflow:airflow'')); ''Content-Type''=''application/json''}; Invoke-WebRequest -Uri ''http://10.9.100.198:8080/api/v1/variables'' -Method POST -Headers `$h -Body `$body -UseBasicParsing"'
"@
Set-Content -Path "F:\Database\av.sql" -Value $sql -Encoding ASCII
$result = & sqlcmd -S localhost -x -i "F:\Database\av.sql" 2>&1
Write-Output $result
